import { test, expect } from '@playwright/test';

test.describe('Add and Delete Elements Functionality', () => {
  test('should add an element and display the delete button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    await page.click('button[onclick="addElement()"]');
    await expect(page).toHaveURL(/.*add_remove_elements\//);
    await page.click('button[onclick="addElement()"]');
    await expect(page).toHaveURL(/.*add_remove_elements\//);
    await expect(page.locator('button[onclick="deleteElement(1)"]')).toBeVisible();
  });

  test('should not change the URL when clicking the delete button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    await page.click('button[onclick="addElement()"]');
    await page.click('button[onclick="deleteElement(1)"]');
    await expect(page).toHaveURL(/.*add_remove_elements\//);
    await expect(page.locator('button[onclick="deleteElement(1)"]')).toBeVisible();
  });
});
